import * as files from "./files";

let mockIsMacValue = false;

vi.mock("./browser", () => ({
  get isMac() {
    return mockIsMacValue;
  },
}));

describe("formatBytes (trial T1, turn 1)", () => {
  it("is the helper's new name", () => {
    expect(files.formatBytes(500)).toBe("500 Bytes");
    expect(files.formatBytes(undefined)).toBe("0 Bytes");
    expect(files.formatBytes(1536)).toBe("1.5 KB");
  });

  it("no longer exports the old name", () => {
    expect("bytesToHumanReadable" in files).toBe(false);
  });
});

import { formatBytes } from "./files";

let mockIsMacValue = false;

vi.mock("./browser", () => ({
  get isMac() {
    return mockIsMacValue;
  },
}));

describe("formatBytes decimals (trial T1, turn 2)", () => {
  it("defaults to two decimal places", () => {
    expect(formatBytes(12345)).toBe("12.06 KB");
  });

  it("takes the number of decimal places", () => {
    expect(formatBytes(12345, 1)).toBe("12.1 KB");
    expect(formatBytes(12345, 0)).toBe("12 KB");
    expect(formatBytes(500, 0)).toBe("500 Bytes");
  });
});
